void calendar_change_by_key(uint8_t directtion,uint8_t day)
{
    uint8_t         days[13] = {
        0,31,28,31,30,31,30,31,31,30,31,30,31
        };
    uint8_t         day_num = 0;
    uint16_t        year;

    year                = calendar_year + 1970;

    if (calendar_month == 2) // 2月,特殊处理
    {
        if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) //闰年，29天
            day_num = days[calendar_month] +1;
        else 
            day_num = days[calendar_month];
        }
    else {
        day_num             = days[calendar_month];
        }

    if (directtion) // 日期增加
    {
        if (calendar_day + day > day_num) {
            if (calendar_month + 1 > 12) {
                if (year >= 2037)
                    return; // 超过2037年就无效

                else {
                    calendar_month      = 1;
                    calendar_year       += 1;
                    calendar_day        = calendar_day + day - day_num;

                    }
                }
            else {
                calendar_day        = calendar_day + day - day_num;
                calendar_month      += 1;
                }
            }
        else {
            calendar_day        = calendar_day + day;
            }
        }
    else {
        if (calendar_day - day <= 0) {
            if (calendar_month == 1) //跨年
            {
                if (year <= 1970)
                    return; // 小于1970无效

                calendar_month      = 12;
                calendar_year       -= 1;
                calendar_day        = 31 + calendar_day - day; //12月31天
                }
            else {
                calendar_month      -= 1;

                if (calendar_month == 2) {
                    if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) //闰年，29天
                        day_num = days[calendar_month] +1;
                    else 
                        day_num = days[calendar_month];
                    }
                else 
                    day_num = days[calendar_month];

                calendar_day        = day_num + calendar_day - day;
                }
            }
        else {
            calendar_day        = calendar_day - day;
            }
        }
}


void tools_calendar_app_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    char            nongli_year[16] = {
        0
        };
    char            nongli_month[16] = {
        0
        };
    __inf("tools_calendar_app_ui_event_actions 00 =%d\r\n",event_code);

    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("tools_calendar_app_ui_event_actions11 LV_EVENT_KEY:%d\r\n",key);

                if (key == LV_KEY_UP) {
                    //__inf("LV_KEY_UP,child_id:%d,child_cnt:%d\r\n",child_id,child_cnt);
                    calendar_change_by_key(0,7);
                    lv_calendar_set_today_date(ui_FpToolsCalendarIndex,calendar_year + 1970,calendar_month,
                        calendar_day);
                    lv_calendar_set_showed_date(ui_FpToolsCalendarIndex,calendar_year + 1970,calendar_month);

                    sprintf(nongli_year,"%04d.%02d",calendar_year + 1970,calendar_month);
                    lv_label_set_text(ui_FpToolsCalendarDate,nongli_year);
                    nongli(calendar_year + 1970,calendar_month,calendar_day,nongli_year,nongli_month);
                    lv_label_set_text(ui_FpToolsCalendarNongLi,nongli_month);

                    }
                else if (key == LV_KEY_DOWN) {

                    calendar_change_by_key(1,7);
                    lv_calendar_set_today_date(ui_FpToolsCalendarIndex,calendar_year + 1970,calendar_month,
                        calendar_day);
                    lv_calendar_set_showed_date(ui_FpToolsCalendarIndex,calendar_year + 1970,calendar_month);

                    sprintf(nongli_year,"%04d.%02d",calendar_year + 1970,calendar_month);
                    lv_label_set_text(ui_FpToolsCalendarDate,nongli_year);
                    nongli(calendar_year + 1970,calendar_month,calendar_day,nongli_year,nongli_month);
                    lv_label_set_text(ui_FpToolsCalendarNongLi,nongli_month);
                    }
                else if (key == LV_KEY_LEFT) {
                    calendar_change_by_key(0,1);
                    lv_calendar_set_today_date(ui_FpToolsCalendarIndex,calendar_year + 1970,calendar_month,
                        calendar_day);
                    lv_calendar_set_showed_date(ui_FpToolsCalendarIndex,calendar_year + 1970,calendar_month);

                    sprintf(nongli_year,"%04d.%02d",calendar_year + 1970,calendar_month);
                    lv_label_set_text(ui_FpToolsCalendarDate,nongli_year);
                    nongli(calendar_year + 1970,calendar_month,calendar_day,nongli_year,nongli_month);
                    lv_label_set_text(ui_FpToolsCalendarNongLi,nongli_month);
                    }
                else if (key == LV_KEY_RIGHT) {
                    calendar_change_by_key(1,1);
                    lv_calendar_set_today_date(ui_FpToolsCalendarIndex,calendar_year + 1970,calendar_month,
                        calendar_day);
                    lv_calendar_set_showed_date(ui_FpToolsCalendarIndex,calendar_year + 1970,calendar_month);

                    sprintf(nongli_year,"%04d.%02d",calendar_year + 1970,calendar_month);
                    lv_label_set_text(ui_FpToolsCalendarDate,nongli_year);
                    nongli(calendar_year + 1970,calendar_month,calendar_day,nongli_year,nongli_month);
                    lv_label_set_text(ui_FpToolsCalendarNongLi,nongli_month);
                    }
                else if (key == LV_KEY_DEL) {
                    uint8_t         index = 1;      // 

                    if (shortcut_in == 0x80) {
                        alv_am_app_exit_action_all();
                        }
                    else 
                        alv_am_win_jump_action(NULL,"tools_menu",(void *) &index);
                    }
                else if ((key == LV_KEY_ESC) || (key == LV_KEY_ENTER)) {
                    alv_am_win_jump_action(NULL,"tool_cal_item",NULL);
                    }
                else if (key == LV_KEY_END)
                    alv_am_app_exit_action_all();


                }
            break;

        default:
            break;
        }


}


