static uint32_t get_tools_calendar_date_value_year_childId(uint32_t child_cnt)
{
    /*Modify manually*/
    lv_obj_t *      ui_tools_calendar_child = NULL;
    uint32_t        child_id;

    for (child_id = 0; child_id < child_cnt; child_id++) {
        ui_tools_calendar_child = lv_obj_get_child(ui_FpToolsCalendarDateValueYearIndex,child_id);

        if (lv_obj_has_state(ui_tools_calendar_child,LV_STATE_FOCUSED)) {
            break;
            }

        }

    if (child_id >= child_cnt) {
        child_id            = 0;
        }

    //__inf("get_tools_calendar_childId:%d,child_cnt:%d\r\n",child_id,child_cnt);
    return child_id;
}


