static uint32_t get_tools_calendar_alarm_childId(uint32_t child_cnt)
{
    /*Modify manually*/
    lv_obj_t *      ui_tools_child = NULL;
    uint32_t        child_id;

    for (child_id = 0; child_id < child_cnt; child_id++) {
        ui_tools_child      = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,child_id);

        if (lv_obj_has_state(ui_tools_child,LV_STATE_FOCUSED)) {
            break;
            }

        }

    if (child_id >= child_cnt) {
        child_id            = 0;
        }

    //__inf("get_tools_childId:%d,child_cnt:%d\r\n",child_id,child_cnt);
    return child_id;
}


/**********************
 *	 GLOBAL FUNCTIONS
 **********************/
void tools_calendar_app_alarm_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    uint32_t        child_cnt = lv_obj_get_child_cnt(ui_FpToolsCalendarAlarmIndex);
    uint32_t        child_id = get_tools_calendar_alarm_childId(child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;

    //	__inf("tools_calendar_app_alarm_ui_event_actions 00 =%d\r\n",event_code);
    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("tools_calendar_app_alarm_ui_event_actions11 LV_EVENT_KEY:%d\r\n",key);

                if (key == LV_KEY_UP) {
                    //__inf("LV_KEY_UP,child_id:%d,child_cnt:%d\r\n",child_id,child_cnt);
                    if (child_id != 0) {
                        pre_focus_obj       = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);



                        get_focus_obj       = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,child_id - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        if ((child_id - 1) == 0) {
                            lv_obj_scroll_to_y(ui_FpToolsCalendarAlarmIndex,0,LV_ANIM_OFF);

                            }
                        else {
                            lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                            }

                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,child_cnt - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        //__inf("get_focus_obj :%d\r\n",lv_obj_has_state(get_focus_obj, LV_STATE_FOCUSED));
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                        }

                    app_fp_play_tts_menu(lv_label_get_text(get_focus_obj));
                    }
                else if (key == LV_KEY_DOWN) {

                    if (child_id != child_cnt - 1) {
                        pre_focus_obj       = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,child_id + 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpToolsCalendarAlarmIndex,0);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_obj_scroll_to_y(ui_FpToolsCalendarAlarmIndex,0,LV_ANIM_OFF);

                        }

                    app_fp_play_tts_menu(lv_label_get_text(get_focus_obj));
                    }
                else if (key == LV_KEY_LEFT) {

                    }
                else if (key == LV_KEY_DEL) {
                    //uint8_t index = 0;	// 回退到设置的显示设置选项
                    alv_am_win_jump_action(NULL,"tool_cal_todo",(void *) calendar_todo_content);
                    }
                else if ((key == LV_KEY_ESC) || (key == LV_KEY_ENTER)) {
                    if (child_id == 1) // 不需要闹钟提醒的备忘录
                    {
                        //					uint8_t index = 0;	// 回退到设置的显示设置选项
                        s32             ret;
                        todolist_all_nvram_param_t todolist_all;
                        todolist_content_param_t todolist_content;

                        ret                 = aic_md_read(MD_ID_TOOLS_TODO,sizeof(todolist_all_nvram_param_t),
                            &todolist_all);

                        if (ret) {
                            APP_LOGI("read net cfg error 0x%x\n",ret);
                            }

                        ret                 = aic_md_read(MD_ID_TOOLS_TODO_CONTENT,sizeof(todolist_content_param_t),
                            &todolist_content);

                        if (ret) {
                            APP_LOGI("read net cfg error 0x%x\n",ret);
                            }

                        if (ui_FpToolsCalendarTodoSelected == 0xff) // 新的备忘录
                        {
                            for (uint8_t i = 0; i < 10; i++) {
                                if (todolist_all.todolist[i].year < 1970 || todolist_all.todolist[i].year > 2037) {
                                    ui_FpToolsCalendarTodoSelected = i;
                                    break;
                                    }
                                }

                            todolist_all.todolist[ui_FpToolsCalendarTodoSelected].year = calendar_year + 1970;
                            todolist_all.todolist[ui_FpToolsCalendarTodoSelected].month = calendar_month;
                            todolist_all.todolist[ui_FpToolsCalendarTodoSelected].day = calendar_day;
                            todolist_all.todolist[ui_FpToolsCalendarTodoSelected].hour = 0xff;
                            todolist_all.todolist[ui_FpToolsCalendarTodoSelected].min = 0xff;
                            strcpy(todolist_content.todo_content[ui_FpToolsCalendarTodoSelected].content,
                                calendar_todo_content);
                            }
                        else {
                            todolist_all.todolist[ui_FpToolsCalendarTodoSelected].hour = 0xff;
                            todolist_all.todolist[ui_FpToolsCalendarTodoSelected].min = 0xff;
                            memset(todolist_content.todo_content[ui_FpToolsCalendarTodoSelected].content,0,
                                strlen(todolist_content.todo_content[ui_FpToolsCalendarTodoSelected].content));
                            strcpy(todolist_content.todo_content[ui_FpToolsCalendarTodoSelected].content,
                                calendar_todo_content);
                            }

                        ret                 = aic_md_write(MD_ID_TOOLS_TODO,sizeof(todolist_all_nvram_param_t),
                            &todolist_all);

                        if (ret) {
                            APP_LOGI("read net cfg error 0x%x\n",ret);
                            }

                        ret                 = aic_md_write(MD_ID_TOOLS_TODO_CONTENT,sizeof(todolist_content_param_t),
                            &todolist_content);

                        if (ret) {
                            APP_LOGI("read net cfg error 0x%x\n",ret);
                            }

                        tools_calendar_alarm_timer_start();

                        }
                    else {
                        if (ui_FpToolsCalendarTodoSelected == 0xff) // 新的备忘录			
                            alv_am_win_jump_action(NULL,"tool_cal_time",NULL);
                        else 
                            alv_am_win_jump_action(NULL,"tool_cal_date",NULL);

                        }

                    //ui_FpToolsSelected = child_id;
                    //alv_am_win_jump_action(NULL,tools_calendar_alarm_sub_win[child_id],NULL);				
                    }
                else if (key == LV_KEY_END)
                    alv_am_app_exit_action_all();


                }
            break;

        default:
            break;
        }


}


