extern void display_todolist(uint8_t direction,uint8_t browser_status);
extern uint8_t del_todolist(void); // 返回0，表示没有备忘录了


void tools_calendar_app_todobrowser_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("tools_calendar_app_item_ui_event_actions11 LV_EVENT_KEY:%d\r\n",key);

                if (key == LV_KEY_DEL) {
                    if (tools_calendar_todo_status == 3) // 从删除界面跳转到编辑界面
                    {
                        ui_FpToolsCalendarTodoSelected = 0xff;
                        alv_am_win_jump_action(NULL,"tool_cal_todo",(void *) calendar_todo_content);
                        }
                    else 
                        alv_am_win_jump_action(NULL,"tool_cal_item",(void *) &ui_FpToolsSelected);
                    }
                else if (key == LV_KEY_ESC) {
                    // 编辑
                    s32             ret;

                    todolist_content_param_t todolist_content;

                    if (tools_calendar_todo_status == 3) // 从删除界面跳转到浏览界面无编辑功能
                        return;

                    ret                 = aic_md_read(MD_ID_TOOLS_TODO_CONTENT,sizeof(todolist_content_param_t),
                        &todolist_content);

                    if (ret) {
                        APP_LOGI("read net cfg error 0x%x\n",ret);
                        }

                    memset(calendar_todo_content,0,50);
                    strcpy(calendar_todo_content,
                        todolist_content.todo_content[ui_FpToolsCalendarTodoSelected].content);

                    alv_am_win_jump_action(NULL,"tool_cal_todo",(void *) calendar_todo_content);
                    }
                else if (key == LV_KEY_ENTER) {
                    alv_am_win_jump_action(NULL,"tool_cal_delsure",NULL);

                    // 删除
                    }
                else if (key == LV_KEY_UP) {
                    // 
                    display_todolist(0,tools_calendar_todo_status);
                    }
                else if (key == LV_KEY_DOWN) {
                    // 
                    display_todolist(1,tools_calendar_todo_status);
                    }
                else if (key == LV_KEY_END)
                    alv_am_app_exit_action_all();


                }
            break;

        default:
            break;
        }


}


