extern lv_timer_t * tools_calendar_tododoing_one_minute_timer;
lv_timer_t *    tools_calendar_tododoing_timer;


static void tools_calendar_tododoing_timer_event_cb(struct _lv_timer_t *timer)
{
    if (tools_calendar_tododoing_timer) {
        lv_timer_del(tools_calendar_tododoing_timer);
        tools_calendar_tododoing_timer = NULL;
        lv_obj_add_flag(ui_FpToolsCalendarTodoDoingDelayHint,LV_OBJ_FLAG_HIDDEN); /// Flags
        alv_am_win_exit_action_by_app("tools","tool_cal_doing",NULL);
        }
}


void tools_calendar_tododoing_timer_start(void)
{

    if (tools_calendar_tododoing_timer == NULL) {
        tools_calendar_tododoing_timer = lv_timer_create(tools_calendar_tododoing_timer_event_cb,1500,0);
        lv_obj_clear_flag(ui_FpToolsCalendarTodoDoingDelayHint,LV_OBJ_FLAG_HIDDEN); /// Flags					
        }

    ps_data_msg_send_call_ring_stop(NULL);

}


void tools_calendar_app_tododoing_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if (tools_calendar_tododoing_timer && (event_code == LV_EVENT_KEY))
        return;

    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("tools_calendar_app_item_ui_event_actions11 LV_EVENT_KEY:%d\r\n",key);

                if ((key == LV_KEY_ESC) || (key == LV_KEY_ENTER)) {
                    //uint8_t index = 0;	// 回退到日历的显示设置选项
                    if (tools_calendar_tododoing_one_minute_timer) {
                        lv_timer_del(tools_calendar_tododoing_one_minute_timer);
                        tools_calendar_tododoing_one_minute_timer = NULL;

                        }

                    //active_recent_alarm(3);
                    active_recent_alarm(0);
                    active_calendar_delay(alarm_doing_number + 3);
                    tools_calendar_tododoing_timer_start();
                    }
                else if (key == LV_KEY_DEL) {
                    if (tools_calendar_tododoing_one_minute_timer) {
                        lv_timer_del(tools_calendar_tododoing_one_minute_timer);
                        tools_calendar_tododoing_one_minute_timer = NULL;

                        }

                    reset_power_on_alarm_id();

                    //aos_del_alarm_time();
                    if (copy_alarm_para == (alarm_doing_number + 3)) {
                        copy_alarm_para     = 0xff;
                        aos_memset((u8 *) &copy_alarm_time,0,sizeof(aos_systime));
                        }

                    active_recent_alarm(0);
                    custom_remove_alarm_by_number(alarm_doing_number + 3);

                    //tools_calendar_tododoing_timer_start();
                    ps_data_msg_send_call_ring_stop(NULL);
                    alv_am_win_exit_action_by_app("tools","tool_cal_doing",NULL);
                    }
                else if (key == LV_KEY_END) {
                    if (tools_calendar_tododoing_one_minute_timer) {
                        lv_timer_del(tools_calendar_tododoing_one_minute_timer);
                        tools_calendar_tododoing_one_minute_timer = NULL;

                        }

                    reset_power_on_alarm_id();

                    //aos_del_alarm_time();
                    if (copy_alarm_para == (alarm_doing_number + 3)) {
                        copy_alarm_para     = 0xff;
                        aos_memset((u8 *) &copy_alarm_time,0,sizeof(aos_systime));
                        }

                    active_recent_alarm(0);
                    custom_remove_alarm_by_number(alarm_doing_number + 3);

                    //tools_calendar_tododoing_timer_start();
                    ps_data_msg_send_call_ring_stop(NULL);
                    alv_am_app_exit_action_all();
                    }

                }
            break;

        default:
            break;
        }


}


// 
static uint32_t app_musicplayer_play_status;
extern uint8_t get_alarm_level(void);

void tools_calendar_tododoing_win_active(lv_obj_t * win,void * p_param)
{
    extern uint32_t app_musicplayer_get_play_status();
    extern void app_musicplayer_stop();

    if (app_musicplayer_get_play_status())
        app_musicplayer_play_status = 1;

    app_musicplayer_stop();

    app_tts_stop();
    app_recorder_stop();

    if (get_ring_play_status())
        ps_data_msg_send_call_ring_stop();

    settings_fp_flow_set_master_volume(get_alarm_level(),get_alarm_ring(),60 * 1000,NULL); // 最大音量
    backlight_turn_on();
}


void tools_calendar_tododoing_win_deactive(lv_obj_t * win,void * p_param)
{

    if (false == alv_am_app_is_exist("call")) {
        ps_data_msg_send_call_ring_stop();

        if (app_musicplayer_play_status) {
            app_musicplayer_resume();
            app_musicplayer_play_status = 0;
            }
        }
    else {
        if (app_musicplayer_play_status) {
            set_fp_call_other_app_music_play_status(1);
            app_musicplayer_play_status = 0;
            }

        }
}


void tools_calendar_tododoing_win_focus(lv_obj_t * win,void * p_param)
{
    ui_FpToolsCalendarTodoDoing_screen_init(p_param);
    lv_disp_load_scr(ui_FpToolsCalendarTodoDoing);
    backlight_turn_on_always();
}


void tools_calendar_tododoing_win_defocus(lv_obj_t * win,void * p_param)
{
    if (ui_FpToolsCalendarTodoDoing)
        lv_obj_del_delayed_custom(ui_FpToolsCalendarTodoDoing,500);

    ui_FpToolsCalendarTodoDoing = NULL;
    backlight_exit_turn_on_always();
}


